export function serializeGroup(group: GroupEntity, opts: SerializeOptions, path: string[]): Json {
  const xid = `/${group.plural}/${group.id}`;
  const out: Json = {
    [`${group.singular}id`]: group.id,
    self: ref(opts, xid),
    xid,
    epoch: group.epoch,
    createdat: group.createdat,
    modifiedat: group.modifiedat,
    ...group.attrs,
  };

  for (const [plural, resources] of group.resources) {
    const resourcePath = [...path, plural];
    const members: Json = {};
    for (const [rid, resource] of resources) {
