var messageCmd = &cobra.Command{
	Use:   "message",
	Short: "Read the message registry",
	Long: "Read the xRegistry message registry — the catalog of CloudEvents messages, their payload " +
		"schemas, and the endpoints that produce them. These commands are read-only; the registry itself " +
		"is authored in git.",
}

// messageFlags are shared by every message subcommand: all of them fetch
// the registry's export document.
type messageFlags struct {
	registryURL string
	output      string
}

// fetchExport resolves the registry URL (flag > env > context > config),
// builds a client, and fetches the export document. The "not configured"
// error is a usage error — the user can fix it with a flag — while fetch
// failures are runtime errors naming the URL.
func fetchExport(ctx context.Context, registryURL string) (*xregistry.Export, error) {
	cfg, err := config.Load()
	if err != nil {
		return nil, err
	}
	resolved := cfg.Resolve(config.Flags{RegistryURL: registryURL})
	base, err := resolved.RequireRegistryURL()
	if err != nil {
		return nil, &usageError{err: err}
	}
	client, err := xregistry.NewClient(base, xregistry.WithUserAgent("intropy-cli/"+version))
	if err != nil {
		return nil, &usageError{err: err}
	}
	return client.Export(ctx)
}

// resolveMessage wraps Export.ResolveMessage so a not-found answer carries
// the follow-up hint the user needs next, per the house error voice.
func resolveMessage(doc *xregistry.Export, ref string) (*xregistry.ResolvedMessage, error) {
	r, err := doc.ResolveMessage(ref)
	var nf *xregistry.MessageNotFoundError
	if errors.As(err, &nf) {
		return nil, fmt.Errorf("%w\nuse 'int message list' to see the messages in the registry", err)
	}
	return r, err
}

func init() {
	rootCmd.AddCommand(messageCmd)
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/signal"
	"sort"
	"syscall"
	"text/tabwriter"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
	"github.com/spf13/cobra"
)

// message list prints every message in the registry, one row each, with
// the channel its producers publish on. Fetching lives in
// internal/xregistry; this file is flag plumbing and table formatting.
var messageListOpts messageFlags

// messageListEntry is one row of `message list`, in both output formats.
type messageListEntry struct {
	Message     string `json:"message"`
	Group       string `json:"group"`
	Dataschema  string `json:"dataschema,omitempty"`
	Pubsub      string `json:"pubsub,omitempty"`
	Topic       string `json:"topic,omitempty"`
	channel     string
}

var messageListCmd = &cobra.Command{
	Use:   "list",
	Short: "List the messages in the registry",
	Long: "List every message in the registry, one row each: the message id (which is the CloudEvents type), " +
		"its group, its payload schema, and the <pubsub>/<topic> channel its producer publishes on. " +
		"Pass a message id to `int message show` for the full subscription recipe. Use --output json for a " +
		"machine-readable document.",
	Args: usageArgs(cobra.NoArgs),
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(messageListOpts.output, "plain", "json"); err != nil {
			return err
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		doc, err := fetchExport(ctx, messageListOpts.registryURL)
		if err != nil {
			return err
		}
		entries := listMessages(doc)

		if messageListOpts.output == "json" {
			if entries == nil {
				entries = []messageListEntry{}
			}
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(entries)
		}

		if len(entries) == 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "no messages found")
			return nil
		}
		tw := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 2, ' ', 0)
		fmt.Fprintln(tw, "MESSAGE\tGROUP\tSCHEMA\tCHANNEL")
		for _, e := range entries {
			fmt.Fprintf(tw, "%s\t%s\t%s\t%s\n", e.Message, e.Group, orDash(e.Dataschema), orDash(e.channel))
		}
		return tw.Flush()
	},
}

// listMessages flattens the export document into one entry per message,
// sorted by message id so output is deterministic regardless of map order.
// The channel comes from the group's first producer endpoint; a group with
// no producer declared leaves it empty rather than failing the listing.
func listMessages(doc *xregistry.Export) []messageListEntry {
	var entries []messageListEntry
	for gid, g := range doc.MessageGroups {
		channel := ""
		if eps := doc.ProducerEndpointsFor(gid); len(eps) > 0 {
			channel = eps[0].Channel
		}
		pubsub, topic, _ := xregistry.SplitChannel(channel)
		for mid, m := range g.Messages {
			e := messageListEntry{
				Message: mid,
				Group:   gid,
				Pubsub:  pubsub,
				Topic:   topic,
				channel: channel,
			}
			if v := m.DefaultVersion(); v != nil {
				e.Dataschema = schemaIDFromXid(v.DataschemaXid)
			}
			entries = append(entries, e)
		}
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Message < entries[j].Message })
	return entries
}

// schemaIDFromXid extracts the schema id from a dataschema xid — the last
// path segment — for a column that has no room for the whole reference.
func schemaIDFromXid(xid string) string {
	if xid == "" {
		return ""
	}
	base := xid
	for i := len(xid) - 1; i >= 0; i-- {
		if xid[i] == '/' {
			base = xid[i+1:]
			break
		}
	}
	return base
}

func orDash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

func init() {
	f := messageListCmd.Flags()
	f.StringVar(&messageListOpts.registryURL, "registry-url", "", flagUsageRegistryURL)
	f.StringVarP(&messageListOpts.output, "output", "o", "plain", flagUsageOutput)
	messageCmd.AddCommand(messageListCmd)
}

