package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/config"
)

// messageFixture is the /export document the test registry serves: two
// messages in two groups, one group with a producer, one without.
const messageFixture = `{
  "registryid": "intropy",
  "messagegroups": {
    "io.intropy.maxbo.product": {
      "messagegroupid": "io.intropy.maxbo.product",
      "messages": {
        "io.intropy.maxbo.product.export": {
          "messageid": "io.intropy.maxbo.product.export",
          "xid": "/messagegroups/io.intropy.maxbo.product/messages/io.intropy.maxbo.product.export",
          "name": "Product export completed",
          "versions": {
            "1": {
              "versionid": "1",
              "isdefault": true,
              "envelope": "CloudEvents/1.0",
              "envelopemetadata": {
                "type": {"value": "io.intropy.maxbo.product.export", "type": "string"},
                "source": {"value": "urn:maxbo:perfion", "type": "uri"}
              },
              "protocol": "AMQP/1.0",
              "dataschemaxid": "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1"
            }
          }
        }
      }
    },
    "io.intropy.acme.orders": {
      "messagegroupid": "io.intropy.acme.orders",
      "messages": {
        "io.intropy.acme.orders.placed": {
          "messageid": "io.intropy.acme.orders.placed",
          "xid": "/messagegroups/io.intropy.acme.orders/messages/io.intropy.acme.orders.placed",
          "versions": {
            "1": {"versionid": "1", "isdefault": true}
          }
        }
      }
    }
  },
  "schemagroups": {
    "io.intropy.maxbo.product": {
      "schemagroupid": "io.intropy.maxbo.product",
      "schemas": {
        "product-export.v1": {
          "schemaid": "product-export.v1",
          "versions": {
            "1": {"versionid": "1", "isdefault": true, "format": "JsonSchema/draft/2020-12"}
          }
        }
      }
    }
  },
  "endpoints": {
    "perfion-extractor": {
      "endpointid": "perfion-extractor",
      "usage": ["producer"],
      "channel": "product-distribution-pubsub/sbt-test-product-extractor-001",
      "messagegroups": ["/messagegroups/io.intropy.maxbo.product"]
    }
  }
}`

// messageRegistry starts a test registry and isolates the run from the
// developer's own config and environment, so the only way to reach a
// registry is the flag each test passes.
func messageRegistry(t *testing.T, body string, status int) *httptest.Server {
	t.Helper()
	t.Setenv("XDG_CONFIG_HOME", t.TempDir())
	t.Setenv(config.EnvRegistryURL, "")
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write([]byte(body))
	}))
	t.Cleanup(srv.Close)
	return srv
}

func runMessage(t *testing.T, args ...string) (stdout, stderr string, err error) {
	t.Helper()
	outBuf, errBuf := &bytes.Buffer{}, &bytes.Buffer{}
	resetRootIO(t, outBuf, errBuf)
	// Flag values are package-level and survive across tests; reset them so
	// one test's --output cannot leak into the next.
	t.Cleanup(func() {
		messageListOpts = messageFlags{}
		messageShowOpts = messageFlags{}
	})
	rootCmd.SetArgs(args)
	err = rootCmd.Execute()
	return outBuf.String(), errBuf.String(), err
}

func TestMessageListTable(t *testing.T) {
	srv := messageRegistry(t, messageFixture, http.StatusOK)
	stdout, _, err := runMessage(t, "message", "list", "--registry-url", srv.URL)
	if err != nil {
		t.Fatalf("execute: %v", err)
	}
	for _, want := range []string{
		"MESSAGE", "GROUP", "SCHEMA", "CHANNEL",
		"io.intropy.maxbo.product.export", "product-export.v1",
		"product-distribution-pubsub/sbt-test-product-extractor-001",
		"io.intropy.acme.orders.placed",
	} {
		if !strings.Contains(stdout, want) {
			t.Errorf("table missing %q; got:\n%s", want, stdout)
		}
	}
	// Sorted by message id: acme before maxbo.
	if strings.Index(stdout, "io.intropy.acme.orders.placed") > strings.Index(stdout, "io.intropy.maxbo.product.export") {
		t.Errorf("rows not sorted by message id:\n%s", stdout)
	}
	// The group with no producer renders a dash, not an empty cell.
	if !strings.Contains(stdout, "-") {
		t.Errorf("producer-less message should render a dash channel:\n%s", stdout)
	}
}

func TestMessageListJSON(t *testing.T) {
	srv := messageRegistry(t, messageFixture, http.StatusOK)
	stdout, _, err := runMessage(t, "message", "list", "--registry-url", srv.URL, "--output", "json")
	if err != nil {
		t.Fatalf("execute: %v", err)
	}
	var entries []messageListEntry
	if err := json.Unmarshal([]byte(stdout), &entries); err != nil {
		t.Fatalf("stdout is not the JSON document: %v\n%s", err, stdout)
	}
	if len(entries) != 2 {
		t.Fatalf("entries = %d, want 2", len(entries))
	}
	var export *messageListEntry
	for i := range entries {
		if entries[i].Message == "io.intropy.maxbo.product.export" {
			export = &entries[i]
		}
	}
	if export == nil {
		t.Fatal("export message missing from JSON")
	}
	if export.Pubsub != "product-distribution-pubsub" || export.Topic != "sbt-test-product-extractor-001" {
		t.Errorf("channel = %q / %q", export.Pubsub, export.Topic)
	}
	if export.Dataschema != "product-export.v1" {
		t.Errorf("dataschema = %q", export.Dataschema)
	}
}

func TestMessageListEmpty(t *testing.T) {
	srv := messageRegistry(t, `{"registryid": "intropy"}`, http.StatusOK)

	stdout, stderr, err := runMessage(t, "message", "list", "--registry-url", srv.URL)
	if err != nil {
		t.Fatalf("execute: %v", err)
	}
	if !strings.Contains(stderr, "no messages found") {
		t.Errorf("empty notice should be on stderr, got %q", stderr)
	}
	if stdout != "" {
		t.Errorf("stdout should be empty, got %q", stdout)
	}

	stdout, _, err = runMessage(t, "message", "list", "--registry-url", srv.URL, "--output", "json")
	if err != nil {
		t.Fatalf("execute: %v", err)
	}
	if strings.TrimSpace(stdout) != "[]" {
		t.Errorf("json empty state should be [], got %q", stdout)
	}
}

func TestMessageShowPlain(t *testing.T) {
	srv := messageRegistry(t, messageFixture, http.StatusOK)
	stdout, _, err := runMessage(t, "message", "show", "io.intropy.maxbo.product.export", "--registry-url", srv.URL)
	if err != nil {
		t.Fatalf("execute: %v", err)
	}
	for _, want := range []string{
		"io.intropy.maxbo.product.export",
		"Product export completed",
		"group:", "io.intropy.maxbo.product",
		"type:", "source:", "urn:maxbo:perfion",
		"dataschema:", "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1",
		"schema version:", "1",
		"subscribe:",
		"pubsub:", "product-distribution-pubsub",
		"topic:", "sbt-test-product-extractor-001",
		"producer:", "perfion-extractor",
	} {
		if !strings.Contains(stdout, want) {
			t.Errorf("show output missing %q; got:\n%s", want, stdout)
		}
	}
}

func TestMessageShowNoProducer(t *testing.T) {
	srv := messageRegistry(t, messageFixture, http.StatusOK)
	stdout, _, err := runMessage(t, "message", "show", "io.intropy.acme.orders.placed", "--registry-url", srv.URL)
	if err != nil {
		t.Fatalf("execute: %v (a missing producer is not an error)", err)
	}
	if !strings.Contains(stdout, "no producer endpoint declared for io.intropy.acme.orders") {
		t.Errorf("expected the no-producer line, got:\n%s", stdout)
	}
}

func TestMessageShowUnknown(t *testing.T) {
	srv := messageRegistry(t, messageFixture, http.StatusOK)
	_, _, err := runMessage(t, "message", "show", "io.intropy.nope", "--registry-url", srv.URL)
	if err == nil {
		t.Fatal("expected error")
	}
	if !strings.Contains(err.Error(), `message "io.intropy.nope" not found`) {
		t.Errorf("error should front-load the id, got %q", err)
	}
	if !strings.Contains(err.Error(), "int message list") {
		t.Errorf("error should suggest the list command, got %q", err)
	}
}

func TestMessageShowAmbiguous(t *testing.T) {
	// The same message id declared in a second group makes the bare id
	// ambiguous; the error must list the xids that disambiguate.
	ambiguous := strings.Replace(messageFixture,
		`"io.intropy.acme.orders.placed"`, `"io.intropy.maxbo.product.export"`, 1)
	srv := messageRegistry(t, ambiguous, http.StatusOK)
	_, _, err := runMessage(t, "message", "show", "io.intropy.maxbo.product.export", "--registry-url", srv.URL)
	if err == nil {
		t.Fatal("expected error")
	}
	for _, want := range []string{"matches multiple messages", "/messagegroups/io.intropy.maxbo.product/messages/", "/messagegroups/io.intropy.acme.orders/messages/"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error missing %q: %q", want, err)
		}
	}
}

func TestMessageShowByXid(t *testing.T) {
	srv := messageRegistry(t, messageFixture, http.StatusOK)
	stdout, _, err := runMessage(t, "message", "show",
		"/messagegroups/io.intropy.maxbo.product/messages/io.intropy.maxbo.product.export",
		"--registry-url", srv.URL)
	if err != nil {
		t.Fatalf("execute: %v", err)
	}
	if !strings.Contains(stdout, "Product export completed") {
		t.Errorf("xid form should resolve the message, got:\n%s", stdout)
	}
}

func TestMessageShowJSON(t *testing.T) {
	srv := messageRegistry(t, messageFixture, http.StatusOK)
	stdout, _, err := runMessage(t, "message", "show", "io.intropy.maxbo.product.export", "--registry-url", srv.URL, "--output", "json")
	if err != nil {
		t.Fatalf("execute: %v", err)
	}
	var d messageShowDocument
	if err := json.Unmarshal([]byte(stdout), &d); err != nil {
		t.Fatalf("stdout is not the JSON document: %v\n%s", err, stdout)
	}
	if d.Type != "io.intropy.maxbo.product.export" || d.Source != "urn:maxbo:perfion" {
		t.Errorf("type/source = %q / %q", d.Type, d.Source)
	}
	if d.Schema == nil || d.Schema.ID != "product-export.v1" || d.Schema.Version != "1" {
		t.Errorf("schema = %+v", d.Schema)
	}
	if len(d.Producers) != 1 || d.Producers[0].Pubsub != "product-distribution-pubsub" {
		t.Errorf("producers = %+v", d.Producers)
	}
}

func TestMessageRegistryUnreachable(t *testing.T) {
	srv := messageRegistry(t, "boom", http.StatusInternalServerError)
	_, _, err := runMessage(t, "message", "list", "--registry-url", srv.URL)
	if err == nil {
		t.Fatal("expected error")
	}
	if !strings.Contains(err.Error(), srv.URL) || !strings.Contains(err.Error(), "500") {
		t.Errorf("error should name the URL and status, got %q", err)
	}
}

func TestMessageRegistryNotConfigured(t *testing.T) {
	t.Setenv("XDG_CONFIG_HOME", t.TempDir())
	t.Setenv(config.EnvRegistryURL, "")
	_, _, err := runMessage(t, "message", "list")
	if err == nil {
		t.Fatal("expected error")
	}
	var ue *usageError
	if !errors.As(err, &ue) {
		t.Errorf("unconfigured registry is a usage error, got %T: %v", err, err)
	}
	for _, want := range []string{"--registry-url", config.EnvRegistryURL, "registryUrl"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error should mention %q: %q", want, err)
		}
	}
}

func TestMessageInvalidOutput(t *testing.T) {
	_, _, err := runMessage(t, "message", "list", "--output", "yaml")
	var ue *usageError
	if !errors.As(err, &ue) {
		t.Errorf("invalid --output is a usage error, got %v", err)
	}
}

