// resolveRegistryURL layers a --registry-url flag value over the
// environment, active context, and config file. A config that cannot be
// read degrades to the flag value alone rather than failing the command —
// the same leniency seedOrganization applies, since a missing config file
// is the common case.
func resolveRegistryURL(flag string) string {
	cfg, err := config.Load()
	if err != nil {
		return flag
	}
	return cfg.Resolve(config.Flags{RegistryURL: flag}).RegistryURL
}

