		t.Fatal("expected a conflict error")
	}
	for _, want := range []string{"sbt-test-product-extractor-001", "some-other-topic", "--set topic="} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error should name %q: %q", want, err)
		}
	}
}

func TestCreateMessageRefUnknownMessage(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
	registry := messageRegistryServer(t)

	err := Create(context.Background(), CreateOptions{
		Template:    "subscriber",
		OutputDir:   filepath.Join(t.TempDir(), "out"),
		Version:     "v1.0.0",
		SetValues:   map[string]any{"name": "loader", "subscription": "orders.placed"},
		NoInput:     true,
		Stderr:      &bytes.Buffer{},
		Source:      lib.sourceOpts(t.TempDir(), nil),
		RegistryURL: registry.URL,
	})
	if err == nil {
		t.Fatal("expected an unknown-message error")
	}
	if !strings.Contains(err.Error(), "close matches: io.intropy.acme.orders.placed") {
		t.Errorf("error should list close matches, got %q", err)
	}
}

func TestCreateMessageRefAmbiguousMessage(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
	registry := messageRegistryServer(t)

	err := Create(context.Background(), CreateOptions{
		Template:    "subscriber",
		OutputDir:   filepath.Join(t.TempDir(), "out"),
		Version:     "v1.0.0",
		SetValues:   map[string]any{"name": "loader", "subscription": "io.intropy.maxbo.product.export"},
		NoInput:     true,
