// injectWiringValue sets a wiring value from the registry. An identical
// value already present is accepted. A conflicting one is an error when it
// came from --set — the user stated intent about this message — and a
// noted override otherwise, since defaults and derived values declare
// conventions the registry's fact about this message outranks.
func injectWiringValue(values map[string]any, key, want, messageXid string, sets map[string]any, notes io.Writer) error {
	existing, ok := values[key]
	if !ok || existing == nil || existing == "" {
		values[key] = want
		return nil
	}
	if s, _ := existing.(string); s == want {
		return nil
	}
	if _, explicit := sets[key]; explicit {
		return fmt.Errorf("%s: the registry declares %q for %s, but the values set %q\nchange --set %s= to match the registry, or fix the registry's channel", key, want, messageXid, existing, key)
	}
	values[key] = want
	if notes != nil {
		fmt.Fprintf(notes, "%s: %s (from the message registry; was %q)\n", key, want, existing)
	}
	return nil
}

