// message-level attributes onto the version; the resource field is the
// fallback for documents assembled otherwise.
func (r *ResolvedMessage) DisplayName() string {
	if r.Version != nil && r.Version.Name != "" {
		return r.Version.Name
	}
	return r.Message.Name
}

// DisplayDescription returns the message's description, with the same
// version-first rule as DisplayName.
func (r *ResolvedMessage) DisplayDescription() string {
	if r.Version != nil && r.Version.Description != "" {
		return r.Version.Description
	}
	return r.Message.Description
}

