// printField prints one aligned key-value line, skipping empty values so
// the detail view never shows a label with nothing after it. The column
// width fits the longest key in use ("schema version").
func printField(out io.Writer, key, value string) {
	if value == "" {
		return
	}
	fmt.Fprintf(out, "%-16s%s\n", key+":", value)
}

