// Temporary end-to-end verification for the loader template's message-ref
// annotation (U5). Not for commit: it reads the sibling intropy-templates
// checkout and a live registry on :8787.
package template

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const loaderManifestPath = "/Users/robinhultman/dev/intropy/tooling/intropy-templates/loader/template.yaml"
const devRegistryURL = "http://127.0.0.1:8787"

func loaderManifestForCLI(t *testing.T) string {
	t.Helper()
	data, err := os.ReadFile(loaderManifestPath)
	if err != nil {
		t.Skip("intropy-templates checkout not available")
	}
	// The library renamed the domain ahead of this CLI branch.
	return strings.Replace(string(data), "intropy.io/v1", "intropy.dev/v1", 1)
}

func loaderLibrary(t *testing.T) *testLibrary {
	t.Helper()
	return newTestLibrary(t, "v1.0.0", map[string]string{
		"loader/template.yaml":            loaderManifestForCLI(t),
		"loader/skeleton/wiring.txt.tmpl": "topic={{ .topic }} pubsub={{ .pubsub }} contract={{ .contract }}\n",
	})
}

func TestLoaderManifestAnnotationLoads(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "template.yaml")
	if err := os.WriteFile(path, []byte(loaderManifestForCLI(t)), 0o644); err != nil {
		t.Fatal(err)
	}
	tmpl, err := LoadTemplate(path)
	if err != nil {
		t.Fatalf("LoadTemplate: %v", err)
	}
	var sub, topic, contract *FieldSpec
	for i, f := range tmpl.Fields() {
		switch f.Name {
		case "subscription":
			sub = &tmpl.Fields()[i]
		case "topic":
			topic = &tmpl.Fields()[i]
		case "contract":
			contract = &tmpl.Fields()[i]
		}
	}
	if sub == nil || !sub.MessageRef {
		t.Errorf("subscription should be a message ref: %+v", sub)
	}
	if topic == nil || topic.Required {
		t.Errorf("topic should be optional now: %+v", topic)
	}
	if contract == nil || contract.Required {
		t.Errorf("contract should be optional now: %+v", contract)
	}
}

func TestLoaderSubscriptionResolvesAgainstDevRegistry(t *testing.T) {
	lib := loaderLibrary(t)
	outDir := filepath.Join(t.TempDir(), "out")
	var stderr bytes.Buffer

	err := Create(context.Background(), CreateOptions{
		Template:  "loader",
		OutputDir: outDir,
		Version:   "v1.0.0",
		SetValues: map[string]any{
			"name":         "ProductLoader",
			"organization": "Maxbo",
			"subscription": "io.intropy.maxbo.product.export",
		},
		NoInput:     true,
		Stderr:      &stderr,
		Source:      lib.sourceOpts(t.TempDir(), nil),
		RegistryURL: devRegistryURL,
	})
	if err != nil {
		t.Fatalf("Create: %v\nstderr: %s", err, stderr.String())
	}
	rendered, err := os.ReadFile(filepath.Join(outDir, "wiring.txt"))
	if err != nil {
		t.Fatal(err)
	}
	want := "topic=sbt-test-product-extractor-001 pubsub=product-distribution-pubsub contract=ProductExport"
	if !strings.Contains(string(rendered), want) {
		t.Errorf("rendered = %q, want %q", rendered, want)
	}
	scaffold := readScaffoldT(t, outDir)
	if len(scaffold.Subscriptions) != 1 || scaffold.Subscriptions[0].SchemaID != "product-export.v1" {
		t.Errorf("subscriptions = %+v", scaffold.Subscriptions)
	}
	t.Logf("recorded subscription: %+v", scaffold.Subscriptions[0])
}

func TestLoaderLegacyTopicContractFlowUnchanged(t *testing.T) {
	lib := loaderLibrary(t)
	outDir := filepath.Join(t.TempDir(), "out")

	err := Create(context.Background(), CreateOptions{
		Template:  "loader",
		OutputDir: outDir,
		Version:   "v1.0.0",
		SetValues: map[string]any{
			"name":         "OrderLoader",
			"organization": "Acme",
			"topic":        "orders",
			"contract":     "Order",
		},
		NoInput: true,
		Stderr:  &bytes.Buffer{},
		Source:  lib.sourceOpts(t.TempDir(), nil),
		// Unroutable on purpose: the legacy flow must not consult a registry.
		RegistryURL: "http://127.0.0.1:1",
	})
	if err != nil {
		t.Fatalf("legacy flow: %v", err)
	}
	rendered, _ := os.ReadFile(filepath.Join(outDir, "wiring.txt"))
	if !strings.Contains(string(rendered), "topic=orders pubsub=pubsub contract=Order") {
		t.Errorf("legacy wiring changed: %q", rendered)
	}
}

func TestLoaderNeitherSubscriptionNorTopicFailsValidation(t *testing.T) {
	lib := loaderLibrary(t)
	err := Create(context.Background(), CreateOptions{
		Template:  "loader",
		OutputDir: filepath.Join(t.TempDir(), "out"),
		Version:   "v1.0.0",
		SetValues: map[string]any{
			"name":         "OrderLoader",
			"organization": "Acme",
		},
		NoInput: true,
		Stderr:  &bytes.Buffer{},
		Source:  lib.sourceOpts(t.TempDir(), nil),
	})
	if err == nil {
		t.Fatal("expected the anyOf guard to fail")
	}
	t.Logf("validation error: %v", err)
}
