// refreshTemplates drops the resolved release so the next fetch resolves the
// latest one again, then serves the fresh listing. It is how a template
// release cut while the dashboard runs is picked up without a restart —
// the same escape hatch POST /api/topology/refresh offers. The cached
// registry export goes with it: a message published while the dashboard
// runs is the same kind of change.
func (s *apiServer) refreshTemplates(w http.ResponseWriter, r *http.Request) {
	s.tagMu.Lock()
	s.tag = ""
	s.tagMu.Unlock()
	s.exportMu.Lock()
	s.export = nil
	s.exportTried = false
	s.exportMu.Unlock()
	s.listTemplates(w, r)
}

// registryExport returns the cached registry export, fetching on first
// use. A fetch failure is cached too (exportTried) — the suggestions
// endpoint runs per form edit, and retrying a down registry on every
// keystroke would turn a degradation into a stall. The error is not
// retained: callers degrade, they do not report it.
func (s *apiServer) registryExport(ctx context.Context) *xregistry.Export {
	if s.registryURL == "" {
		return nil
	}
	s.exportMu.Lock()
	defer s.exportMu.Unlock()
	if s.exportTried {
		return s.export
	}
	s.exportTried = true
	client, err := xregistry.NewClient(s.registryURL, xregistry.WithUserAgent(s.templates.userAgent))
	if err != nil {
		return nil
	}
	s.export, _ = client.Export(ctx)
	return s.export
}

