// suggestForDir populates each field's suggestions from the workspace under
// dir, chained off the values the form has already confirmed — the same
// inputs `int create` prompts with (workspace facts plus confirmed values).
// A message-ref field's pick list comes from the registry instead: the
// workspace has no opinion on what the catalog declares.
func (s *apiServer) suggestForDir(r *http.Request, result *template.DescribeResult, dir string, confirmed map[string]any) error {
	facts, err := s.factsForDir(dir)
	if err != nil {
		return err
	}
	suggestions := template.Suggest(result.Fields, facts, confirmed)
	var messageIDs []string
	for _, f := range result.Fields {
		if !f.MessageRef {
			continue
		}
		if messageIDs == nil {
			messageIDs = registryMessageIDs(s.registryExport(r.Context()))
		}
		suggestions[f.Name] = messageIDs
	}
	for i := range result.Fields {
		result.Fields[i].Suggestions = suggestions[result.Fields[i].Name]
	}
	return nil
}

// registryMessageIDs lists the export's message ids, sorted, for a
// message-ref field's pick list. A nil export — no registry configured, or
// unreachable — yields nil: the field stays a plain text input.
func registryMessageIDs(doc *xregistry.Export) []string {
	if doc == nil {
		return nil
	}
	var ids []string
	for _, g := range doc.MessageGroups {
		for id := range g.Messages {
			ids = append(ids, id)
		}
	}
	sort.Strings(ids)
	return ids
}

