package dashboard

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"
)

// messageRefTemplateYAML declares a message-ref parameter the way the
// loader template does: optional, with the wiring carried by other
// parameters and a spec.values pubsub convention.
const messageRefTemplateYAML = `apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: subscriber
spec:
  parameters:
    type: object
    required: [name]
    properties:
      name:
        type: string
      subscription:
        type: string
        x-intropy-message-ref: true
      topic:
        type: string
      contract:
        type: string
  values:
    pubsub: 'pubsub'
`

// registryFixture is the export document the test registry serves: one
// produced message with a schema.
const registryFixture = `{
  "registryid": "intropy",
  "messagegroups": {
    "io.intropy.maxbo.product": {
      "messagegroupid": "io.intropy.maxbo.product",
      "messages": {
        "io.intropy.maxbo.product.export": {
          "messageid": "io.intropy.maxbo.product.export",
          "xid": "/messagegroups/io.intropy.maxbo.product/messages/io.intropy.maxbo.product.export",
          "versions": {
            "1": {
              "versionid": "1",
              "isdefault": true,
              "dataschemaxid": "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1"
            }
          }
        }
      }
    }
  },
  "schemagroups": {
    "io.intropy.maxbo.product": {
      "schemagroupid": "io.intropy.maxbo.product",
      "schemas": {
        "product-export.v1": {
          "schemaid": "product-export.v1",
          "versions": {"1": {"versionid": "1", "isdefault": true}}
        }
      }
    }
  },
  "endpoints": {
    "perfion-extractor": {
      "endpointid": "perfion-extractor",
      "usage": ["producer"],
      "channel": "product-distribution-pubsub/sbt-test-product-extractor-001",
      "messagegroups": ["/messagegroups/io.intropy.maxbo.product"]
    }
  }
}`

func newMessageRefLibrary(t *testing.T, tag string) *templatetest.Library {
	t.Helper()
	return templatetest.NewLibrary(t, tag, map[string]string{
		"subscriber/template.yaml":            messageRefTemplateYAML,
		"subscriber/skeleton/wiring.txt.tmpl": "topic={{ .topic }} pubsub={{ .pubsub }} contract={{ .contract }}\n",
	})
}

// registryServer serves the export fixture and counts requests, so tests
// can assert the export is fetched once and cached.
func registryServer(t *testing.T, hits *atomic.Int32) *httptest.Server {
	t.Helper()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits.Add(1)
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(registryFixture))
	}))
	t.Cleanup(srv.Close)
	return srv
}

// messageRefHandler builds a handler with the fixture library and the
// registry URL set — the combination cmd/intropy/dashboard.go wires from
// the config in production.
func messageRefHandler(t *testing.T, root string, lib *templatetest.Library, registryURL string) http.Handler {
	t.Helper()
	h, api, err := newHandler(root, "test", templateProviders(lib.Source(t)))
	if err != nil {
		t.Fatal(err)
	}
	api.registryURL = registryURL
	return h
}

func messageRefSuggestions(t *testing.T, body []byte) []string {
	t.Helper()
	var got struct {
		Fields []struct {
			Name        string   `json:"name"`
			MessageRef  bool     `json:"messageRef"`
			Suggestions []string `json:"suggestions"`
		} `json:"fields"`
	}
	if err := json.Unmarshal(body, &got); err != nil {
		t.Fatal(err)
	}
	for _, f := range got.Fields {
		if f.Name == "subscription" {
			if !f.MessageRef {
				t.Error("subscription field should carry messageRef in the API")
			}
			return f.Suggestions
		}
	}
	t.Fatal("no subscription field in response")
	return nil
}

func TestGetTemplateMessageRefSuggestionsFromRegistry(t *testing.T) {
	lib := newMessageRefLibrary(t, "v1")
	var hits atomic.Int32
	registry := registryServer(t, &hits)
	root := t.TempDir()
	h := messageRefHandler(t, root, lib, registry.URL)

	rec := get(t, h, "/api/templates/subscriber?dir=.")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200: %s", rec.Code, rec.Body)
	}
	got := messageRefSuggestions(t, rec.Body.Bytes())
	if len(got) != 1 || got[0] != "io.intropy.maxbo.product.export" {
		t.Errorf("suggestions = %v", got)
	}

	// The suggestions refresh endpoint reads the same cached export — a
	// per-keystroke refresh must not re-dial the registry.
	rec = get(t, h, "/api/templates/subscriber/suggestions?dir=.")
	if rec.Code != http.StatusOK {
		t.Fatalf("suggestions status = %d: %s", rec.Code, rec.Body)
	}
	if hits.Load() != 1 {
		t.Errorf("registry fetched %d times, want 1 (cached)", hits.Load())
	}
}

func TestGetTemplateMessageRefWithoutRegistryDegrades(t *testing.T) {
	lib := newMessageRefLibrary(t, "v1")
	root := t.TempDir()

	// No registry configured: the form still renders, the field is a plain
	// text input.
	h := messageRefHandler(t, root, lib, "")
	rec := get(t, h, "/api/templates/subscriber?dir=.")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200: %s", rec.Code, rec.Body)
	}
	if got := messageRefSuggestions(t, rec.Body.Bytes()); len(got) != 0 {
		t.Errorf("suggestions without registry = %v, want none", got)
	}

	// A configured but unreachable registry degrades the same way.
	h = messageRefHandler(t, root, lib, "http://127.0.0.1:1")
	rec = get(t, h, "/api/templates/subscriber?dir=.")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200: %s", rec.Code, rec.Body)
	}
	if got := messageRefSuggestions(t, rec.Body.Bytes()); len(got) != 0 {
		t.Errorf("suggestions with registry down = %v, want none", got)
	}
}

func TestCreateTemplateResolvesSubscription(t *testing.T) {
	lib := newMessageRefLibrary(t, "v1")
	var hits atomic.Int32
	registry := registryServer(t, &hits)
	root := t.TempDir()
	h := messageRefHandler(t, root, lib, registry.URL)

	rec := postJSON(t, h, "/api/templates/subscriber/create",
		`{"name":"product-loader","values":{"subscription":"io.intropy.maxbo.product.export"}}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d, want 201: %s", rec.Code, rec.Body)
	}
	var got struct {
		Values        map[string]any `json:"values"`
		Subscriptions []struct {
			Parameter     string `json:"parameter"`
			Message       string `json:"message"`
			SchemaID      string `json:"schemaid"`
			SchemaVersion string `json:"schemaVersion"`
		} `json:"subscriptions"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatal(err)
	}
	if got.Values["topic"] != "sbt-test-product-extractor-001" {
		t.Errorf("topic = %v", got.Values["topic"])
	}
	if got.Values["pubsub"] != "product-distribution-pubsub" {
		t.Errorf("pubsub = %v", got.Values["pubsub"])
	}
	if got.Values["contract"] != "ProductExport" {
		t.Errorf("contract = %v", got.Values["contract"])
	}
	if len(got.Subscriptions) != 1 || got.Subscriptions[0].SchemaID != "product-export.v1" {
		t.Errorf("subscriptions = %+v", got.Subscriptions)
	}
}

func TestCreateTemplateSubscriptionWithoutRegistry(t *testing.T) {
	lib := newMessageRefLibrary(t, "v1")
	root := t.TempDir()
	h := messageRefHandler(t, root, lib, "")

	rec := postJSON(t, h, "/api/templates/subscriber/create",
		`{"name":"product-loader","values":{"subscription":"io.intropy.maxbo.product.export"}}`)
	if rec.Code != http.StatusInternalServerError {
		t.Errorf("status = %d, want 500 (server is missing configuration): %s", rec.Code, rec.Body)
	}
	if !strings.Contains(rec.Body.String(), "no registry is configured") {
		t.Errorf("body should say what is missing: %s", rec.Body)
	}
}

func TestCreateTemplateUnknownSubscription(t *testing.T) {
	lib := newMessageRefLibrary(t, "v1")
	var hits atomic.Int32
	registry := registryServer(t, &hits)
	root := t.TempDir()
	h := messageRefHandler(t, root, lib, registry.URL)

	rec := postJSON(t, h, "/api/templates/subscriber/create",
		`{"name":"product-loader","values":{"subscription":"io.intropy.nope"}}`)
	if rec.Code != http.StatusUnprocessableEntity {
		t.Errorf("status = %d, want 422 (the form highlights the field): %s", rec.Code, rec.Body)
	}
	if !strings.Contains(rec.Body.String(), "io.intropy.nope") {
		t.Errorf("body should name the reference: %s", rec.Body)
	}
}
